// KDP paperback rules, deliberately limited to the existing 6 x 9 export.
export const BACK_COVER_LIMIT = 1500;
// Match the cover calculator's input range. Publishing ranges below are advisory.
export const COVER_PAGE_MIN = 24;
export const COVER_PAGE_MAX = 830;
export const PAPER_CHOICES = {
  'bw-white': { label: 'Black-and-white on white paper', factor: 0.002252, min: 24, max: 828 },
  'bw-cream': { label: 'Black-and-white on cream paper', factor: 0.0025, min: 24, max: 776 },
  'standard-color': { label: 'Standard color on white paper', factor: 0.002252, min: 72, max: 600 },
  'premium-color': { label: 'Premium color on white paper', factor: 0.002347, min: 24, max: 828 },
} as const;
export type PaperChoice = keyof typeof PAPER_CHOICES;
export interface PaperbackCoverOptions { paper: PaperChoice; backText: string; backgroundColor?: string }

export function coverDimensions(pdfPages: number, paper: PaperChoice) {
  const choice = PAPER_CHOICES[paper];
  if (!choice || !Number.isSafeInteger(pdfPages) || pdfPages < 1) {
    throw new Error('The finished PDF has an invalid page count or paper choice.');
  }
  if (pdfPages < COVER_PAGE_MIN || pdfPages > COVER_PAGE_MAX) {
    throw new Error(`Page count must be between ${COVER_PAGE_MIN}–${COVER_PAGE_MAX}. This PDF has ${pdfPages} pages.`);
  }
  const printPages = Math.ceil(pdfPages / 2) * 2;
  const spine = printPages * choice.factor;
  return { pdfPages, printPages, spine, width: 12.25 + spine, height: 9.25 };
}

export function paperbackPublishingNote(pdfPages: number, paper: PaperChoice) {
  const { printPages } = coverDimensions(pdfPages, paper);
  const choice = PAPER_CHOICES[paper];
  if (printPages >= choice.min && printPages <= choice.max) return '';
  return `KDP lists ${choice.min}–${choice.max} pages for ${choice.label.toLowerCase()} at 6 × 9 inches. You can calculate this cover, but this page count is outside that publishing range.`;
}

export function characterCount(text: string) { return Array.from(text).length; }
export function limitBackText(text: string) { return Array.from(text).slice(0, BACK_COVER_LIMIT).join(''); }

// Front panel: 6 x 9 trim, plus bleed at top, bottom, and outer edge.
export const FRONT_WIDTH = 6.125;
export const FRONT_HEIGHT = 9.25;
export const COVER_BACKGROUND = '#f3efe5';

export function coverBackground(value: unknown): string {
  return typeof value === 'string' && /^#[0-9a-f]{6}$/i.test(value) ? value.toLowerCase() : COVER_BACKGROUND;
}

// Choose the larger contrast ratio against the selected RGB background.
export function coverTextColor(background: string): '#000000' | '#ffffff' {
  const hex = coverBackground(background).slice(1);
  const rgb = [0, 2, 4].map(offset => {
    const channel = parseInt(hex.slice(offset, offset + 2), 16) / 255;
    return channel <= 0.04045 ? channel / 12.92 : ((channel + 0.055) / 1.055) ** 2.4;
  });
  const luminance = rgb[0]! * 0.2126 + rgb[1]! * 0.7152 + rgb[2]! * 0.0722;
  return (luminance + 0.05) / 0.05 >= 1.05 / (luminance + 0.05) ? '#000000' : '#ffffff';
}
export type FrontFit = 'fill' | 'border';

export function frontPlacement(width: number, height: number, fit: FrontFit = 'fill') {
  if (![width, height].every(value => Number.isFinite(value) && value > 0)) throw new Error('The cover image has no usable dimensions.');
  const scale = fit === 'border' ? Math.min(5.5 / width, 8.5 / height) : Math.max(FRONT_WIDTH / width, FRONT_HEIGHT / height);
  const printWidth = width * scale;
  const printHeight = height * scale;
  const x = ((fit === 'border' ? 6 : FRONT_WIDTH) - printWidth) / 2;
  const y = fit === 'border' ? 0.125 + (9 - printHeight) / 2 : (FRONT_HEIGHT - printHeight) / 2;
  return { width: printWidth, height: printHeight, x, y, dpi: 1 / scale,
    cropSides: fit === 'fill' && (printWidth - FRONT_WIDTH) / scale > 1,
    cropTopBottom: fit === 'fill' && (printHeight - FRONT_HEIGHT) / scale > 1 };
}

export function frontImageWarnings(width: number, height: number, fit: FrontFit) {
  const placement = frontPlacement(width, height, fit);
  const warnings: string[] = [];
  if (fit === 'border') warnings.push('This option adds a border in your chosen background color around the front image. It will be visible in print and may look uneven after trimming. Choose Fill front cover or a different image if you do not want it.');
  if (placement.cropSides || placement.cropTopBottom) warnings.push(`To fill the front cover without an added border, the ${placement.cropSides ? 'sides' : 'top and bottom'} of this image will be cropped. Check the preview, especially any lettering near the edges.`);
  if (placement.dpi < 299.9) warnings.push(`This image is ${width} × ${height} pixels, about ${Math.round(placement.dpi)} DPI at this size, and may look blurry in print. For the same image shape at 300 DPI, use at least ${Math.ceil(width * 300 / placement.dpi)} × ${Math.ceil(height * 300 / placement.dpi)} pixels. You can still use this image.`);
  return warnings;
}

'use client';

import React, { useEffect, useRef, useState } from 'react';
import { FRONT_WIDTH, FRONT_HEIGHT, type FrontFit } from '@/lib/paperback-cover';
import type { PreparedFrontImage } from '@/lib/paperback-cover-browser';

interface Props {
  loadEpubCover: () => Promise<Blob>;
  onChange: (front: PreparedFrontImage | null) => void;
  file: File | null;
  fit: FrontFit;
  backgroundColor: string;
  saved?: boolean;
  onFileChange: (file: File | null) => void;
  onFitChange: (fit: FrontFit) => void;
}

export default function PaperbackFrontImage({ loadEpubCover, onChange, file, fit, backgroundColor, saved = false, onFileChange, onFitChange }: Props) {
  const [front, setFront] = useState<PreparedFrontImage | null>(null);
  const [error, setError] = useState('');
  const input = useRef<HTMLInputElement>(null);
  const epubCover = useRef<Promise<Blob> | null>(null);

  useEffect(() => { epubCover.current = null; }, [loadEpubCover]);
  useEffect(() => {
    let active = true;
    setFront(null); onChange(null); setError('');
    const prepare = async () => {
      if (file && !(['image/jpeg', 'image/png'].includes(file.type) || (!file.type && /\.(jpe?g|png)$/i.test(file.name)))) {
        throw new Error('Choose a JPG or PNG image for the front cover.');
      }
      if (!file && !epubCover.current) {
        epubCover.current = loadEpubCover().catch(failure => { epubCover.current = null; throw failure; });
      }
      const blob = file ?? await epubCover.current!;
      if (!active) return;
      const { prepareFrontImage } = await import('@/lib/paperback-cover-browser');
      if (!active) return;
      const prepared = await prepareFrontImage(blob, fit, backgroundColor);
      if (active) { setFront(prepared); onChange(prepared); }
    };
    void prepare().catch(failure => {
      if (active) setError(failure instanceof Error ? failure.message : 'This image could not be opened. Choose another JPG or PNG.');
    });
    return () => { active = false; onChange(null); };
  }, [file, fit, backgroundColor, loadEpubCover, onChange]);

  return (
    <div className='space-y-2'>
      <h4 className='font-semibold'>Front-cover image</h4>
      <p className='text-xs text-base-content/70'>Choose finished artwork with its title and author. Click Save to keep it with this ebook, replacing any previously saved paperback image.</p>
      <label className='block text-sm'>Choose front-cover image
        <input ref={input} type='file' accept='.jpg,.jpeg,.png,image/jpeg,image/png' className='file-input file-input-bordered file-input-sm mt-1 w-full'
          onChange={event => { const selected = event.target.files?.[0]; event.target.value = ''; if (selected) { onChange(null); setFront(null); onFileChange(selected); } }} />
      </label>
      <div className='flex flex-wrap items-center gap-3 text-sm'>
        <span className='break-all'>{file ? `${file.name} · ${saved ? 'Saved with this ebook' : 'Not saved yet'}` : 'Using the EPUB cover'}</span>
        {file && <button type='button' className='link' onClick={() => { onChange(null); setFront(null); onFileChange(null); if (input.current) input.current.value = ''; }}>Use EPUB cover</button>}
      </div>
      <label className='block text-sm'>Image placement
        <select className='select select-bordered select-sm mt-1 w-full' value={fit}
          onChange={event => { onChange(null); setFront(null); onFitChange(event.target.value as FrontFit); }}>
          <option value='fill'>Fill front cover — no added border</option>
          <option value='border'>Keep whole image — add a border</option>
        </select>
      </label>
      <p className='text-xs text-base-content/70'>Front artwork including bleed: 6.125 × 9.25 inches, about 1838 × 2775 pixels at 300 DPI.</p>
      {error ? <p role='alert' className='text-sm text-error'>{error}</p> : !front ? <p role='status' className='text-sm'>Preparing the front-cover preview…</p> : (
        <>
          <div className='relative mx-auto w-44 max-w-full overflow-hidden' style={{ aspectRatio: `${FRONT_WIDTH} / ${FRONT_HEIGHT}` }}>
            {/* The preview uses the exact panel that will be placed in the PDF. */}
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img src={front.dataUrl} alt='Front-cover preview including bleed' className='block h-full w-full' />
            <div aria-hidden='true' className='pointer-events-none absolute border border-dashed border-white'
              style={{ left: `${0.125 / FRONT_WIDTH * 100}%`, right: `${0.25 / FRONT_WIDTH * 100}%`, top: `${0.25 / FRONT_HEIGHT * 100}%`, bottom: `${0.25 / FRONT_HEIGHT * 100}%`, boxShadow: '0 0 0 1px #333' }} />
          </div>
          <p className='text-xs text-base-content/70'>Dashed guide: keep the title, author name and important details inside. The guide is not printed. PNG transparency is flattened to the chosen background color when you select the image. To change that color inside an uploaded PNG, select the PNG again.</p>
          <p className='text-xs text-base-content/70'>{front.sourceWidth} × {front.sourceHeight} pixels · about {Math.round(front.dpi)} DPI at the chosen size</p>
          {front.warnings.length > 0 && <ul className='list-disc space-y-2 pl-5 text-sm'>{front.warnings.map(message => <li key={message}>{message}</li>)}</ul>}
        </>
      )}
    </div>
  );
}

